public static boolean treeLessThanTree(BinNode<Integer> t1, BinNode<Integer> t2) {
    if (t1 == null) {
        return true;
    }
    return lessThanTree(t2, t1.getValue()) && treeLessThanTree(t1.getLeft(), t2) && treeLessThanTree(t1.getRight(), t2);
}

