public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

public static boolean lessThanTree(BinNode<Integer> t, int x) {
    if (t == null) {
        return true;
    }
    return x < t.getValue() && lessThanTree(t.getLeft(), x) && lessThanTree(t.getRight(), x);
}

exercise.mainCode:
BinNode<Integer> t1 = new BinNode<Integer>(new BinNode<Integer>(1), 3, new BinNode<Integer>(new BinNode<Integer>(4), 5, null));
BinNode<Integer> t2 = new BinNode<Integer>(new BinNode<Integer>(7), 10, new BinNode<Integer>(new BinNode<Integer>(11), 12, new BinNode<Integer>(15)));
System.out.println("סעיף א, בדיקה 1 (העצים מהציורים): " + check(treeLessThanTree(t1, t2), true));
BinNode<Integer> t3 = new BinNode<Integer>(new BinNode<Integer>(1), 3, new BinNode<Integer>(8));
System.out.println("סעיף א, בדיקה 2 (8 ב-t1 לא קטן מ-7 שב-t2): " + check(treeLessThanTree(t3, t2), false));
BinNode<Integer> t4 = new BinNode<Integer>(null, 2, new BinNode<Integer>(7));
System.out.println("סעיף א, בדיקה 3 (ערך שווה, 7 בשני העצים): " + check(treeLessThanTree(t4, t2), false));
System.out.println("סעיף א, בדיקה 4 (t1 הוא null): " + check(treeLessThanTree(null, t2), true));
System.out.println("סעיף א, בדיקה 5 (t2 בצומת אחד): " + check(treeLessThanTree(t1, new BinNode<Integer>(6)), true));

